import { connectLinearCredentials } from "@vercel/connect/eve";
import { defaultLinearAuth, linearChannel } from "eve/channels/linear";
import { stampTrusted } from "../lib/trust.js";

/**
 * Linear channel: Agent Sessions in, Agent Activities out, via Vercel Connect.
 *
 * @remarks
 * Credentials are brokered by Vercel Connect, which supplies the app token and
 * verifies inbound webhooks by their Vercel OIDC signature. The
 * `onAgentSession` hook keeps the default created/prompted dispatch, stamps
 * the caller as trusted (only workspace members can open an Agent Session, so
 * membership is the gate here), and adds the requester's name as session
 * context when Linear provides it, for attribution in progress notes and
 * reports.
 */
export default linearChannel({
  credentials: connectLinearCredentials(
    process.env.LINEAR_CONNECTOR ?? "linear/foreman-agent"
  ),
  onAgentSession: (_ctx, event) => {
    if (event.action !== "created" && event.action !== "prompted") {
      return null;
    }
    const requester = event.agentActivity?.user ?? event.agentSession.creator;
    const context: string[] = [];
    const requesterName = requester?.displayName ?? requester?.name;
    if (requesterName) {
      context.push(`The requesting user is ${requesterName}.`);
    }
    return { auth: stampTrusted(defaultLinearAuth(event)), context };
  },
});

import { defineTool } from "eve/tools";
import { z } from "zod";
import { readDocument } from "#lib/blob.js";
import { factoryBrainKey } from "#lib/factory-brain.js";

/**
 * Tool that loads the shared factory brain from Vercel Blob.
 *
 * @remarks
 * The Blob key is derived from `FACTORY_REPO`, never from model input, so every session on the
 * deployment reads the same shared document (see `factoryBrainKey`). Reading is unrestricted:
 * every run, unattended included, may load the brain for context. Returns `found: false` with an
 * empty `brain` when nothing has been recorded yet, which is a normal state, not an error.
 * Authorization resolves from the ambient Vercel OIDC credentials.
 */
export default defineTool({
  description:
    "Load the factory brain: durable, shared notes about the target repository (build quirks, " +
    "verification gotchas, recurring review findings, conventions). Call it at the start of a " +
    "task and weave relevant facts into the messages you send stations, since stations can't " +
    "read it themselves. Returns empty when the brain has nothing yet.",
  /**
   * Read the factory brain document.
   *
   * @param _input - No input.
   * @returns `found` plus the `brain` Markdown (empty when none), or an `error`.
   */
  async execute() {
    const key = factoryBrainKey();
    try {
      const doc = await readDocument(key);
      if (!doc.found) {
        return { brain: "", found: false };
      }
      return { brain: doc.content, found: true };
    } catch (error) {
      return {
        brain: "",
        error:
          error instanceof Error
            ? error.message
            : "Failed to load the factory brain",
        found: false,
      };
    }
  },
  inputSchema: z.object({}),
  outputSchema: z.object({
    brain: z.string(),
    error: z.string().optional(),
    found: z.boolean(),
  }),
});

