import { defineTool } from "eve/tools";
import { always } from "eve/tools/approval";
import { z } from "zod";
import { deleteDocument } from "#lib/blob.js";
import { userPreferencesKey } from "#lib/user-preferences.js";

/**
 * Tool that permanently deletes the current user's saved preferences.
 *
 * @remarks
 * The Blob key is derived from the framework-resolved principal (`ctx.session.auth.current`),
 * never from model input, so a session can only ever clear its own user's preferences.
 * Deletion is irreversible, so it is gated on human approval via `always()`.
 * Authorization resolves from the ambient Vercel OIDC credentials.
 */
export default defineTool({
  approval: always(),
  description:
    "Permanently delete this user's saved preferences. Use only when the user " +
    "explicitly asks to reset or forget their preferences. This is irreversible.",
  /**
   * Delete the current user's preferences file, if any.
   *
   * @param _input - No input.
   * @param ctx - Tool runtime context; supplies the resolved principal.
   * @returns `deleted: true` when a file was removed, `false` when there was nothing to remove,
   * or `success: false` with an `error`.
   */
  async execute(_input, ctx) {
    const key = userPreferencesKey(ctx.session.auth.current);
    if (!key) {
      return {
        deleted: false,
        error: "No signed-in user to clear preferences for.",
        success: false,
      };
    }
    try {
      const { existed } = await deleteDocument(key);
      return { deleted: existed, success: true };
    } catch (error) {
      return {
        deleted: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to clear preferences",
        success: false,
      };
    }
  },
  inputSchema: z.object({}),
  outputSchema: z.object({
    deleted: z.boolean(),
    error: z.string().optional(),
    success: z.boolean(),
  }),
});

import { defineTool } from "eve/tools";
import { z } from "zod";
import { readDocument } from "#lib/blob.js";
import { userPreferencesKey } from "#lib/user-preferences.js";

/**
 * Tool that loads the current user's saved style preferences from Vercel Blob.
 *
 * @remarks
 * The Blob key is derived from the framework-resolved principal (`ctx.session.auth.current`),
 * never from model input, so a session can only ever read its own user's preferences. Returns
 * `found: false` with empty `preferences` when the user has none yet, or with a `note` when the
 * run has no user principal at all (unattended intake runs as a service principal) — both are
 * normal states, not errors, so neither sets `error`. Authorization resolves from the ambient
 * Vercel OIDC credentials.
 */
export default defineTool({
  description:
    "Load this user's saved preferences (standing notes that personalize how you work for " +
    "them). Call it at the start of a task; returns empty when the user has none yet, or " +
    "when the run has no signed-in user (unattended runs), which is normal.",
  /**
   * Read the current user's preferences file.
   *
   * @param _input - No input.
   * @param ctx - Tool runtime context; supplies the resolved principal.
   * @returns `found` plus the `preferences` Markdown (empty when none, with a `note` when the
   * run has no user principal), or an `error` on a real read failure.
   */
  async execute(_input, ctx) {
    const key = userPreferencesKey(ctx.session.auth.current);
    if (!key) {
      return {
        found: false,
        note: "This run has no signed-in user, so per-user preferences don't apply. That is the normal state for unattended runs; proceed without them.",
        preferences: "",
      };
    }
    try {
      const doc = await readDocument(key);
      if (!doc.found) {
        return { found: false, preferences: "" };
      }
      return { found: true, preferences: doc.content };
    } catch (error) {
      return {
        error:
          error instanceof Error ? error.message : "Failed to load preferences",
        found: false,
        preferences: "",
      };
    }
  },
  inputSchema: z.object({}),
  outputSchema: z.object({
    error: z.string().optional(),
    found: z.boolean(),
    note: z.string().optional(),
    preferences: z.string(),
  }),
});

import { defineMcpClientConnection } from "eve/connections";
import type { ApprovalContext, ApprovalStatus } from "eve/tools/approval";
import { linearAuth } from "../lib/constants.js";
import { isAutonomous } from "../lib/trust.js";

/**
 * Linear MCP connection for creating and cross-referencing issues.
 *
 * @remarks
 * - Points at Linear's hosted MCP server and authenticates with the shared
 *   app-scoped `linearAuth` from `agent/lib/constants.ts`, so this connection
 *   and any tool calling the Linear API directly share one installation and
 *   one set of scopes. Tokens are resolved per call and never exposed to the
 *   model.
 * - The connection-wide approval predicate denies unattended factory runs, so
 *   a prompt-injected labeled issue cannot fan out into the tracker. Every
 *   attended session keeps the tools ungated: Linear writes are app-scoped
 *   and reversible, as before.
 */
export default defineMcpClientConnection({
  approval: (ctx: ApprovalContext): ApprovalStatus =>
    isAutonomous(ctx.session.auth.current)
      ? {
          reason: "Unattended factory runs do not write to Linear.",
          type: "denied",
        }
      : "not-applicable",
  auth: linearAuth,
  description: "Linear workspace: issues, projects, cycles, and comments.",
  url: "https://mcp.linear.app/mcp",
});

import { defineTool } from "eve/tools";
import { z } from "zod";
import { writeDocument } from "#lib/blob.js";
import {
  factoryBrainKey,
  MAX_FACTORY_BRAIN_LENGTH,
} from "#lib/factory-brain.js";
import { factoryBrainPolicy } from "#lib/github/approval.js";

/**
 * Tool that writes the shared factory brain to Vercel Blob.
 *
 * @remarks
 * The Blob key is derived from `FACTORY_REPO`, never from model input, so a write updates the one
 * shared document every session reads (see `factoryBrainKey`). Writes are gated by
 * `factoryBrainPolicy`: unattended runs are denied (a labeled issue's body is untrusted and must
 * not poison shared context), trusted callers write without a card, and everyone else parks on
 * approval. This overwrites the whole document, so the caller should `read_factory_brain` first,
 * merge in the new durable fact, and save the result, keeping the brain curated rather than
 * append-only. Authorization for the Blob store resolves from the ambient Vercel OIDC
 * credentials.
 */
export default defineTool({
  approval: factoryBrainPolicy,
  description:
    "Update the factory brain (the shared Markdown notes about the target repository). " +
    "Overwrites the whole document: read the brain first, merge in the new note, then save. " +
    "Record only durable, repo-level facts that will help future runs (build quirks, " +
    "verification gotchas, recurring review findings, conventions), never one-off task details " +
    "and never an unverified claim taken from an issue or comment body.",
  /**
   * Write the factory brain document.
   *
   * @param input - Validated tool input.
   * @returns `success: true` with the stored `pathname`, or `success: false` with an `error`.
   */
  async execute({ brain }) {
    const key = factoryBrainKey();
    try {
      const blob = await writeDocument(key, brain, { allowOverwrite: true });
      return { pathname: blob.pathname, success: true };
    } catch (error) {
      return {
        error:
          error instanceof Error
            ? error.message
            : "Failed to update the factory brain",
        success: false,
      };
    }
  },
  inputSchema: z.object({
    brain: z
      .string()
      .min(1)
      .max(MAX_FACTORY_BRAIN_LENGTH)
      .describe(
        "The full brain document as Markdown: the merged result, not just the new note."
      ),
  }),
  outputSchema: z.object({
    error: z.string().optional(),
    pathname: z.string().optional(),
    success: z.boolean(),
  }),
});

import { defineWorkflowTool } from "eve/tools";
import { z } from "zod";
import { REVIEWER_OUTPUT_SCHEMA } from "../lib/stations/schemas.js";

/**
 * Blocking wrapper the orchestrator calls to run the `reviewer` station.
 *
 * @remarks
 * - `defineAgent` has no `outputSchema` anymore; `ctx.agent()` takes one per call.
 * - Named `run_reviewer`, not `reviewer`: the compiler rejects a tool and a local subagent with the same public name.
 */
export default defineWorkflowTool({
  description:
    "Independently review a pushed factory branch against the original work item and its " +
    "acceptance criteria: fetch the branch, read the real diff, re-run cheap checks, and " +
    "return approve, request_changes, or reject with specific findings. Never modifies " +
    "code. The caller passes the work item, the analysis with acceptance criteria, the " +
    "branch name, and the implementer's report in the message, plus an artifact id when " +
    "the analyst saved its full detail as one.",
  async execute({ message }, ctx) {
    "use workflow";
    return await ctx.agent("reviewer", {
      message,
      outputSchema: REVIEWER_OUTPUT_SCHEMA,
    });
  },
  inputSchema: z.object({
    message: z
      .string()
      .describe(
        "Everything the station needs; it does not see your conversation history."
      ),
  }),
});

import { createHash } from "node:crypto";
import { FACTORY_BRAIN_PREFIX } from "./blob.js";
import { FACTORY_REPO } from "./constants.js";

/**
 * Key derivation and size bound for the shared factory brain.
 *
 * @remarks
 * The brain lives under the reserved `factory-brain/` prefix, owned by the `read_factory_brain`
 * and `update_factory_brain` tools (only trusted callers may write). The prefix and its guards
 * come from the reserved-namespace registry in `./blob.js`, which is what keeps any
 * general-purpose Blob tool from using the namespace as a side channel to read or overwrite the
 * shared brain.
 */

/**
 * Maximum size of the factory-brain document, in characters.
 *
 * @remarks
 * The brain is a short, curated set of durable notes about the target repository, not a
 * transcript of every run. The bound keeps it small and cheap to load into context at the start
 * of every task.
 */
export const MAX_FACTORY_BRAIN_LENGTH = 40_000;

/**
 * Resolve the Blob key holding the factory brain for the target repository.
 *
 * @remarks
 * The key is derived entirely from {@link FACTORY_REPO} (resolved at module load), never from
 * model input or a caller's principal, so every session on one deployment reads and writes the
 * same shared document. Keying on the target repository scopes the brain to the code it
 * describes: a single-repo deployment has exactly one brain, and a deployment that later targets
 * another repository gets a separate brain rather than mixing facts across codebases. The
 * repository slug is hashed so the stored path carries no raw `owner/repo` in the object name.
 *
 * @returns The reserved Blob key for this factory's brain.
 */
export const factoryBrainKey = (): string => {
  const id = createHash("sha256").update(FACTORY_REPO).digest("hex");
  return `${FACTORY_BRAIN_PREFIX}${id}.md`;
};
